Lemma fbp_Btail : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (rax t1' t2' a0' a1' a2' a3' a4' a5' xs3 xs8 t3' t4' t5' t6' : word) (LF : list fframe) (fb n lo shi spa ff fp : Z) (FB : fbv)
    (Q : mem -> Prop) (m0 mx : mem) (gap : list cell) (tj0 tj1 hjunk sh16 : list byte),
  (spa = bv_unsigned sp + -224 \/ spa = bv_unsigned sp + -240) ->
  stk bsegs mx lo spa ->
  rw_cells bsegs mx spa (fbp_tmp2 tj0 tj1 fb ff) ->
  rw_cells bsegs mx (spa + 96) gap -> Z.of_nat (cells_size gap) = bv_unsigned sp + -200 - spa ->
  rw_cells bsegs mx (bv_unsigned sp + -104) (fbp_saved s11 s10 s9 s8 s7 s6 s5 s4 s3 s2 s1 s0 ra) ->
  rw_cells bsegs mx ff [CB 120 hjunk; C8 (Z_to_bv 64 fp)] ->
  rw_cells bsegs mx (Z.shiftr ff 3 + 2147450880) [CB 16 sh16] ->
  rw_cells bsegs mx fp [C1 (b8 1)] ->
  rw_cells bsegs mx fb (FlatBufCells FB) -> accessible mx fb SZ_FB -> fb mod 8 = 0 -> aplace fb SZ_FB -> (fb + SZ_FB <= lo \/ bv_unsigned sp <= fb) -> fsobj H LF fb SZ_FB ->
  fresh_frame H LF 1 ff fp -> as_RFS H ((1, ff, fp) :: LF) mx -> ACONST mx -> stack0 mx lo shi -> mem_inv bsegs mx -> as_RFS H LF m0 ->
  (forall m', munch (fbp_WA fb ff fp) mx m' -> wmono bsegs mx m' -> Q m') ->
  0 <= fb_begin FB -> fb_begin FB <= fb_in FB <= fb_out FB -> fb_out FB <= fb_end FB -> fb_end FB <= aceil ->
  (fb_begin FB = 0 -> fb_end FB = 0) ->      (* [comment removed for export] *)
  0 <= n -> fb_size FB + n < 2^27 -> n <= fb_cap FB - fb_size FB ->
  lo + 240 <= bv_unsigned sp -> aceil <= lo -> bv_unsigned ra mod 2 = 0 ->
  evt bsegs (fbp_endq_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LF (fbp_WA fb ff fp) lo shi fb (fb_begin FB + fb_size FB) n
               (mkFB (fb_begin FB) (fb_begin FB) (fb_begin FB + fb_size FB) (fb_begin FB + fb_size FB + n) (fb_end FB)) Q mx)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp (Z_to_bv 64 (Z.shiftr (fb + 16) 3 + 2147450880)) t1' t2'
                  sp (Z_to_bv 64 spa)
                  a0' a1' a2' a3' a4' a5' (Z_to_bv 64 ff) (Z_to_bv 64 n)
                  (Z_to_bv 64 ff) xs3 (Z_to_bv 64 fb) (Z_to_bv 64 (Z.shiftr (fb + 8) 3 + 2147450880)) (Z_to_bv 64 (fb + 8))
                  (Z_to_bv 64 (fb_size FB)) xs8 (Z_to_bv 64 2147450880) (Z_to_bv 64 (fb + 16))
                  (Z_to_bv 64 (Z.shiftr ff 3 + 2147450880)) t3' t4' t5' t6')
        F (Z_to_bv 64 0xc3cd8) fc None mx (seg_rom bsegs)).
